import React, { useState, useEffect, useContext } from 'react';
import { Link } from 'react-router-dom';
import { FileText, Clock, CheckCircle2, XCircle, AlertCircle, Calendar, MessageSquare, ExternalLink, ChevronRight, Filter, Search, MoreVertical, Building2, User, ArrowUpRight, Plus, Briefcase, GraduationCap } from 'lucide-react';
import { AppContext } from '../../App';
import { ApplicationService } from '../../domain/applicationService';
import { EmployerService } from '../../domain/employerService';

const Applications = () => {
  const { user, userType } = useContext(AppContext);
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showStatusModal, setShowStatusModal] = useState(false);
  const [selectedApplication, setSelectedApplication] = useState(null);
  const [statusUpdate, setStatusUpdate] = useState({
    status: '',
    feedback: '',
    interviewDate: ''
  });
  const [updateLoading, setUpdateLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    loadApplications();
  }, [userType, user]);

  const loadApplications = async () => {
    try {
      setLoading(true);
      let applicationsData;

      if (userType === 'student') {
        applicationsData = await ApplicationService.getApplicationsByStudent(user.id);
      } else if (userType === 'employer') {
        applicationsData = await EmployerService.getEmployerApplications(user.id);
      } else {
        applicationsData = await ApplicationService.getAllApplications();
      }

      setApplications(applicationsData);
    } catch (error) {
      console.error('Failed to load applications:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleStatusUpdate = (application) => {
    setSelectedApplication(application);
    setStatusUpdate({
      status: application.status,
      feedback: application.feedback || '',
      interviewDate: application.interviewDate || ''
    });
    setMessage('');
    setShowStatusModal(true);
  };

  const handleStatusSubmit = async (e) => {
    e.preventDefault();
    setUpdateLoading(true);
    setMessage('');

    try {
      await ApplicationService.updateApplicationStatus(
        selectedApplication.id,
        statusUpdate.status,
        statusUpdate.feedback,
        statusUpdate.interviewDate || null
      );

      setMessage('Trajectory updated successfully!');
      setTimeout(() => {
        setShowStatusModal(false);
        loadApplications();
      }, 2000);
    } catch (error) {
      setMessage(error.message);
    } finally {
      setUpdateLoading(false);
    }
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      'under_review': { bg: 'bg-gold-500/10', text: 'text-gold-500', border: 'border-gold-500/20', icon: Clock },
      'shortlisted': { bg: 'bg-blue-500/10', text: 'text-blue-400', border: 'border-blue-500/20', icon: AlertCircle },
      'accepted': { bg: 'bg-emerald-500/10', text: 'text-emerald-400', border: 'border-emerald-500/20', icon: CheckCircle2 },
      'rejected': { bg: 'bg-rose-500/10', text: 'text-rose-400', border: 'border-rose-500/20', icon: XCircle }
    };

    const config = statusConfig[status] || { bg: 'bg-pearl-800/10', text: 'text-pearl-600', border: 'border-pearl-800/20', icon: Clock };
    const Icon = config.icon;

    return (
      <span className={`px-3 py-1 rounded-full text-[10px] font-bold border tracking-widest uppercase flex items-center gap-2 w-fit ${config.bg} ${config.text} ${config.border}`}>
        <Icon size={12} /> {status.replace('_', ' ')}
      </span>
    );
  };

  const stats = {
    total: applications.length,
    under_review: applications.filter(app => app.status === 'under_review').length,
    shortlisted: applications.filter(app => app.status === 'shortlisted').length,
    accepted: applications.filter(app => app.status === 'accepted').length,
    rejected: applications.filter(app => app.status === 'rejected').length
  };

  const filteredApplications = applications.filter(app => 
    app.jobTitle.toLowerCase().includes(searchTerm.toLowerCase()) ||
    app.company.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (app.studentName && app.studentName.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  if (loading) {
    return (
      <div className="min-h-screen bg-onyx-900 flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-gold-500/20 border-t-gold-500 rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-onyx-900 pb-24 font-sans text-pearl-200">
      {/* Cinematic Header */}
      <div className="h-64 bg-onyx-950 relative overflow-hidden">
        <div className="absolute inset-0 bg-gold-gradient opacity-[0.03]"></div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[1000px] h-[1000px] bg-gold-500/5 rounded-full blur-[150px]"></div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-full flex flex-col justify-center relative z-10">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
            <div>
              <h1 className="text-4xl md:text-6xl font-serif font-bold text-white tracking-tight leading-none mb-4">
                {userType === 'student' ? 'My Pursuit' : 
                 userType === 'employer' ? 'Candidate Pipeline' : 'Global Trajectories'}
              </h1>
              <p className="text-pearl-500 text-lg font-light tracking-wide italic">Tracking career progression and professional evolution.</p>
            </div>
            <div className="flex items-center gap-4">
               <div className="glass px-6 py-3 rounded-2xl border border-pearl-900/10 text-gold-500 font-bold flex items-center gap-3">
                 <FileText size={20} /> {applications.length} Records
               </div>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-12 relative z-20">

        {/* Statistics Bar */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
          <div className="glass rounded-3xl p-8 border border-pearl-900/10 shadow-xl group hover:border-gold-500/30 transition-all">
            <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-4">Total Submissions</p>
            <div className="flex items-end justify-between">
              <h3 className="text-4xl font-serif font-bold text-white leading-none">{stats.total}</h3>
              <div className="w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center text-pearl-500 group-hover:text-gold-500 transition-colors">
                <FileText size={20} />
              </div>
            </div>
          </div>

          <div className="glass rounded-3xl p-8 border border-pearl-900/10 shadow-xl group hover:border-gold-500/30 transition-all">
            <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-4">Active Review</p>
            <div className="flex items-end justify-between">
              <h3 className="text-4xl font-serif font-bold text-white leading-none">{stats.under_review}</h3>
              <div className="w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center text-pearl-500 group-hover:text-gold-500 transition-colors">
                <Clock size={20} />
              </div>
            </div>
          </div>

          <div className="glass rounded-3xl p-8 border border-pearl-900/10 shadow-xl group hover:border-gold-500/30 transition-all">
            <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-4">Shortlisted</p>
            <div className="flex items-end justify-between">
              <h3 className="text-4xl font-serif font-bold text-white leading-none text-blue-400">{stats.shortlisted}</h3>
              <div className="w-10 h-10 rounded-xl bg-blue-500/5 flex items-center justify-center text-blue-500 group-hover:bg-blue-500 group-hover:text-onyx-900 transition-all">
                <AlertCircle size={20} />
              </div>
            </div>
          </div>

          <div className="glass rounded-3xl p-8 border border-pearl-900/10 shadow-xl group hover:border-gold-500/30 transition-all">
            <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-4">Accepted</p>
            <div className="flex items-end justify-between">
              <h3 className="text-4xl font-serif font-bold text-white leading-none text-emerald-400">{stats.accepted}</h3>
              <div className="w-10 h-10 rounded-xl bg-emerald-500/5 flex items-center justify-center text-emerald-500 group-hover:bg-emerald-500 group-hover:text-onyx-900 transition-all">
                <CheckCircle2 size={20} />
              </div>
            </div>
          </div>
        </div>

        {/* Search & Parameters */}
        <div className="glass rounded-[2.5rem] border border-pearl-900/10 p-4 mb-10 flex flex-col md:flex-row gap-4 items-center shadow-2xl">
          <div className="relative flex-1 w-full">
            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-pearl-700" size={20} />
            <input 
              type="text" 
              placeholder="Search by role, institution, or talent..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-onyx-800/50 border border-pearl-900/10 rounded-2xl py-4 pl-16 pr-6 text-white outline-none focus:border-gold-500/50 transition-all font-light"
            />
          </div>
          <button className="glass px-8 py-4 rounded-2xl border border-pearl-900/10 text-pearl-400 font-bold flex items-center gap-3 hover:bg-white/5 transition-all">
            <Filter size={20} /> Parameters
          </button>
        </div>

        {/* Applications List */}
        <div className="glass rounded-[3rem] border border-pearl-900/10 overflow-hidden shadow-2xl">
          <div className="px-10 py-8 border-b border-pearl-900/10 flex justify-between items-center bg-white/5">
            <h3 className="text-2xl font-serif font-bold text-white">Full Registry</h3>
            <span className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.3em] italic">Placement Logs</span>
          </div>

          {filteredApplications.length > 0 ? (
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-onyx-950/50 text-pearl-700 text-[10px] uppercase tracking-[0.2em] font-black">
                    {userType !== 'student' && <th className="py-8 px-10">Talent</th>}
                    <th className="py-8 px-10">Strategic Role</th>
                    <th className="py-8 px-10">Timeline</th>
                    <th className="py-8 px-10">Status</th>
                    {userType !== 'student' && <th className="py-8 px-10">Engagement</th>}
                    <th className="py-8 px-10 text-right">Operations</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-pearl-900/5">
                  {filteredApplications.map(application => (
                    <tr key={application.id} className="hover:bg-white/[0.02] transition-colors group">
                      {userType !== 'student' && (
                        <td className="py-8 px-10">
                          <Link to={`/student/${application.studentId}`} className="flex items-center gap-4 group/talent">
                            <div className="w-10 h-10 rounded-full bg-onyx-800 border border-pearl-900/10 flex items-center justify-center text-pearl-500 group-hover/talent:border-gold-500/30 transition-all overflow-hidden">
                               <img src={`https://api.dicebear.com/7.x/initials/svg?seed=${application.studentName}`} alt="avatar" className="w-full h-full object-cover grayscale group-hover/talent:grayscale-0 transition-all" />
                            </div>
                            <span className="font-bold text-white group-hover/talent:text-gold-400 transition-colors">{application.studentName}</span>
                          </Link>
                        </td>
                      )}
                      <td className="py-8 px-10">
                        <Link to={`/job/${application.jobId}`} className="block">
                          <p className="font-serif font-bold text-white text-lg tracking-tight leading-tight group-hover:text-gold-400 transition-colors">{application.jobTitle}</p>
                          <p className="text-pearl-600 text-xs font-light tracking-wide flex items-center gap-2 mt-1">
                            <Building2 size={12} className="text-gold-500/30" /> {application.company}
                          </p>
                        </Link>
                      </td>
                      <td className="py-8 px-10">
                        <div className="flex flex-col">
                          <span className="text-pearl-400 font-bold text-sm tabular-nums">{new Date(application.applicationDate).toLocaleDateString()}</span>
                          <span className="text-pearl-700 text-[10px] font-black uppercase tracking-widest mt-1">Applied</span>
                        </div>
                      </td>
                      <td className="py-8 px-10">
                        {getStatusBadge(application.status)}
                      </td>
                      {userType !== 'student' && (
                        <td className="py-8 px-10">
                          {application.interviewDate ? (
                            <div className="flex flex-col">
                              <span className="text-blue-400 font-bold text-sm flex items-center gap-2 uppercase tracking-tighter">
                                <Calendar size={14} /> {new Date(application.interviewDate).toLocaleDateString()}
                              </span>
                              <span className="text-pearl-700 text-[10px] font-black uppercase tracking-widest mt-1">Scheduled</span>
                            </div>
                          ) : (
                            <span className="text-pearl-800 text-xs italic">Pending Engagement</span>
                          )}
                        </td>
                      )}
                      <td className="py-8 px-10 text-right">
                        <div className="flex gap-3 justify-end opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => alert(`Strategic Intent:\n\n${application.coverLetter}`)}
                            className="w-10 h-10 rounded-xl glass border border-pearl-900/10 flex items-center justify-center text-pearl-600 hover:text-white hover:border-pearl-200 transition-all"
                            title="View Strategic Intent"
                          >
                            <FileText size={18} />
                          </button>
                          {(userType === 'employer' || userType === 'admin') && (
                            <button 
                              onClick={() => handleStatusUpdate(application)}
                              className="w-10 h-10 rounded-xl glass border border-pearl-900/10 flex items-center justify-center text-pearl-600 hover:text-gold-500 hover:border-gold-500/30 transition-all"
                              title="Update Status"
                            >
                              <Edit2 size={18} />
                            </button>
                          )}
                          <Link 
                            to={`/job/${application.jobId}`}
                            className="w-10 h-10 rounded-xl glass border border-pearl-900/10 flex items-center justify-center text-pearl-600 hover:text-white hover:border-pearl-200 transition-all"
                          >
                            <ChevronRight size={18} />
                          </Link>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="p-24 text-center">
              <div className="w-24 h-24 bg-onyx-800 rounded-3xl flex items-center justify-center mx-auto mb-8 border border-pearl-900/10">
                <Briefcase className="text-pearl-800" size={40} />
              </div>
              <h4 className="text-2xl font-serif font-bold text-white mb-2">No records found</h4>
              <p className="text-pearl-600 font-light italic mb-8">
                {userType === 'student' 
                  ? "Your professional journey awaits its first chapter."
                  : "No pursuit records are currently cataloged."
                }
              </p>
              {userType === 'student' && (
                <Link to="/jobs" className="inline-flex bg-gold-gradient text-onyx-900 px-8 py-4 rounded-2xl font-black uppercase tracking-[0.2em] text-xs hover:brightness-110 transition-all shadow-gold items-center gap-3">
                   Explore Opportunities <ArrowUpRight size={18} />
                </Link>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Status Transition Modal */}
      {showStatusModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 bg-onyx-950/80 backdrop-blur-md overflow-y-auto">
          <div className="glass rounded-[3rem] w-full max-w-2xl shadow-[0_0_50px_rgba(0,0,0,0.5)] border border-pearl-900/10 overflow-hidden my-auto animate-fade-in-up">
            <div className="px-10 py-8 border-b border-pearl-900/10 flex justify-between items-center bg-white/5">
              <h3 className="text-2xl font-serif font-bold text-white">Status Transition</h3>
              <button onClick={() => setShowStatusModal(false)} className="text-pearl-600 hover:text-white bg-onyx-800 p-2.5 rounded-xl transition-all border border-pearl-900/10">
                <X size={20} />
              </button>
            </div>

            <div className="p-10">
              {message && (
                <div className={`p-5 rounded-2xl mb-8 font-bold text-sm uppercase tracking-widest flex items-start gap-4 ${message.includes('successfully') ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-rose-500/10 text-rose-400 border border-rose-500/20'}`}>
                  {message.includes('successfully') ? <CheckCircle2 size={20} className="shrink-0" /> : <XCircle size={20} className="shrink-0" />}
                  <p>{message}</p>
                </div>
              )}

              {selectedApplication && (
                <div className="mb-10 p-6 bg-white/5 rounded-2xl border border-pearl-900/5">
                  <div className="flex items-center gap-4 mb-4">
                     <div className="w-12 h-12 rounded-xl bg-onyx-800 border border-pearl-900/10 flex items-center justify-center text-gold-500">
                        <GraduationCap size={24} />
                     </div>
                     <div>
                        <h4 className="text-white font-bold text-xl">{selectedApplication.studentName}</h4>
                        <p className="text-pearl-600 text-xs font-medium uppercase tracking-[0.1em]">{selectedApplication.jobTitle}</p>
                     </div>
                  </div>
                </div>
              )}

              <form onSubmit={handleStatusSubmit} className="space-y-8">
                <div>
                  <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3 ml-1">New Strategic Status</label>
                  <select
                    value={statusUpdate.status}
                    onChange={(e) => setStatusUpdate({ ...statusUpdate, status: e.target.value })}
                    required
                    className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white appearance-none cursor-pointer"
                  >
                    <option value="under_review">Under Review</option>
                    <option value="shortlisted">Shortlisted for Interview</option>
                    <option value="accepted">Offer Extended (Accepted)</option>
                    <option value="rejected">Archive (Rejected)</option>
                  </select>
                </div>

                <div>
                  <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3 ml-1">Professional Feedback</label>
                  <textarea
                    rows={4}
                    value={statusUpdate.feedback}
                    onChange={(e) => setStatusUpdate({ ...statusUpdate, feedback: e.target.value })}
                    placeholder="Provide constructive insight for the candidate..."
                    className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-light text-pearl-300 resize-none leading-relaxed"
                  />
                </div>

                {statusUpdate.status === 'shortlisted' && (
                  <div>
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3 ml-1">Interview Engagement</label>
                    <div className="relative group">
                       <Calendar className="absolute left-5 top-1/2 -translate-y-1/2 text-pearl-800 group-focus-within:text-gold-500 transition-colors" size={18} />
                       <input
                         type="datetime-local"
                         value={statusUpdate.interviewDate}
                         onChange={(e) => setStatusUpdate({ ...statusUpdate, interviewDate: e.target.value })}
                         className="w-full px-5 py-4 pl-14 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white"
                       />
                    </div>
                  </div>
                )}

                <div className="pt-6 flex gap-5 justify-end">
                  <button type="button" onClick={() => setShowStatusModal(false)} disabled={updateLoading} className="px-8 py-3.5 rounded-2xl font-bold text-pearl-500 glass hover:text-white transition-all">
                    Dismiss
                  </button>
                  <button type="submit" disabled={updateLoading} className="px-8 py-3.5 rounded-2xl font-bold text-onyx-900 bg-gold-gradient hover:brightness-110 transition-all shadow-gold flex items-center gap-3">
                    {updateLoading ? (
                      <><div className="w-4 h-4 border-2 border-onyx-900/30 border-t-onyx-900 rounded-full animate-spin"></div> Syncing...</>
                    ) : 'Confirm Transition'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// Helper components for missing icons
const Edit2 = ({ size, className }) => (
  <svg 
    width={size} 
    height={size} 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke="currentColor" 
    strokeWidth="2" 
    strokeLinecap="round" 
    strokeLinejoin="round" 
    className={className}
  >
    <path d="M17 3a2.828 2.828 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5L17 3z" />
  </svg>
);

const X = ({ size, className }) => (
  <svg 
    width={size} 
    height={size} 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke="currentColor" 
    strokeWidth="2" 
    strokeLinecap="round" 
    strokeLinejoin="round" 
    className={className}
  >
    <path d="M18 6 6 18" />
    <path d="m6 6 12 12" />
  </svg>
);

export default Applications;
